import{_ as a,o as t,c as i,ao as r}from"./chunks/framework.qiMXmKkH.js";const u=JSON.parse('{"title":"Coming from R","description":"","frontmatter":{},"headers":[],"relativePath":"coming-from-r.md","filePath":"coming-from-r.md","lastUpdated":null}'),o={name:"coming-from-r.md"};function l(n,e,s,h,d,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Coming-from-R" tabindex="-1">Coming from R <a class="header-anchor" href="#Coming-from-R" aria-label="Permalink to &quot;Coming from R {#Coming-from-R}&quot;">​</a></h1><p>You can use DRModels.jl in two different ways.</p><p>If you already work in R with drmTMB, keep using its default R/TMB engine unless you have a specific reason to try Julia. It needs no Julia installation and is the established route for the full drmTMB workflow.</p><p>If you want to work directly in Julia, begin with the <a href="./getting-started">first model tutorial</a>. The model ideas are the same: choose a response family, write a formula for the average response, and add a formula for variability only when that is part of your question.</p><h2 id="Moving-a-familiar-model-to-Julia" tabindex="-1">Moving a familiar model to Julia <a class="header-anchor" href="#Moving-a-familiar-model-to-Julia" aria-label="Permalink to &quot;Moving a familiar model to Julia {#Moving-a-familiar-model-to-Julia}&quot;">​</a></h2><p>The <a href="./rosetta">R and Julia vocabulary</a> page puts common drmTMB and DRModels.jl syntax side by side. It is the best next step when you already have an R model that you understand and want to translate it by hand.</p><h2 id="The-optional-R-bridge" tabindex="-1">The optional R bridge <a class="header-anchor" href="#The-optional-R-bridge" aria-label="Permalink to &quot;The optional R bridge {#The-optional-R-bridge}&quot;">​</a></h2><p>drmTMB also has an optional <code>engine = &quot;julia&quot;</code> route for a limited set of models. It lets you keep writing an R formula while fitting the model with DRModels.jl. This is not required for either package, and it does not make every drmTMB model available in Julia. Follow drmTMB&#39;s <a href="https://itchyshin.github.io/drmTMB/articles/julia-engine.html" target="_blank" rel="noreferrer">Julia-engine setup guide</a> only when the documented example matches your question.</p><p>For the current supported model types, use <a href="./capabilities">What is tested</a>. For models involving spatial, temporal, or other specialised R workflows, stay with the documented native R route unless a Julia example explicitly says otherwise.</p><h2 id="drmTMB-articles-without-a-DRModels.jl-page" tabindex="-1">drmTMB articles without a DRModels.jl page <a class="header-anchor" href="#drmTMB-articles-without-a-DRModels.jl-page" aria-label="Permalink to &quot;drmTMB articles without a DRModels.jl page {#drmTMB-articles-without-a-DRModels.jl-page}&quot;">​</a></h2><p>These drmTMB &quot;Start here&quot; articles have no DRModels.jl counterpart yet. Read them on the drmTMB site, and check any Julia-specific route against <a href="./capabilities">What is tested</a>:</p><ul><li><p><a href="https://itchyshin.github.io/drmTMB/articles/capability-and-limits.html" target="_blank" rel="noreferrer">Capability and limits</a></p></li><li><p><a href="https://itchyshin.github.io/drmTMB/articles/first-week-intervals.html" target="_blank" rel="noreferrer">First-week intervals</a></p></li><li><p><a href="https://itchyshin.github.io/drmTMB/articles/function-map-cheatsheet.html" target="_blank" rel="noreferrer">Function map cheatsheet</a></p></li><li><p><a href="https://itchyshin.github.io/drmTMB/articles/missing-data.html" target="_blank" rel="noreferrer">Missing data</a></p></li><li><p><a href="https://itchyshin.github.io/drmTMB/articles/comparing-with-other-packages.html" target="_blank" rel="noreferrer">Comparing with other packages</a></p></li></ul>',12)])])}const c=a(o,[["render",l]]);export{u as __pageData,c as default};
